<?php
declare(strict_types=1);
require_once __DIR__.'/../config/bootstrap.php';$user=require_login($pdo);$uid=(int)$user['id'];$pageTitle=t('e2ee.legacy_inbox_title');
header('Cache-Control: private, no-store, max-age=0');
header('X-Robots-Tag: noindex, nofollow');
$page=filter_var($_GET['page']??'1',FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>10000]])?:1;
$q=$pdo->prepare('SELECT COUNT(*) FROM market_conversations WHERE buyer_id=? OR seller_id=?');$q->execute([$uid,$uid]);$total=(int)$q->fetchColumn();
$q=$pdo->prepare('SELECT c.*,l.title,l.status,m.message_text,m.cipher_version,m.created_at,u.username AS peer_name,CASE WHEN c.buyer_id=? THEN c.seller_id ELSE c.buyer_id END AS peer_id,EXISTS(SELECT 1 FROM market_messages n WHERE n.listing_id=c.listing_id AND n.receiver_id=? AND n.sender_id=CASE WHEN c.buyer_id=? THEN c.seller_id ELSE c.buyer_id END AND n.is_read=0) AS unread FROM market_conversations c JOIN market_listings l ON l.id=c.listing_id JOIN market_messages m ON m.id=c.last_message_id JOIN users u ON u.id=CASE WHEN c.buyer_id=? THEN c.seller_id ELSE c.buyer_id END WHERE c.buyer_id=? OR c.seller_id=? ORDER BY c.last_message_id DESC LIMIT 25 OFFSET '.(($page-1)*25));$q->execute([$uid,$uid,$uid,$uid,$uid,$uid]);$threads=$q->fetchAll();
include __DIR__.'/../includes/header.php';?>
<main class="container"><div class="page-heading"><h1><?=h($pageTitle)?></h1><p><?=h(t('e2ee.legacy_inbox_help'))?></p></div>
<?php if(e2ee_enabled()):?><p><a class="button" href="/user/secure-chat.php"><?=h(t('e2ee.devices'))?></a></p><?php endif;?>
<?php if(!$threads):?><section class="panel"><p><?=h(t('e2ee.legacy_inbox_empty'))?></p><a class="button" href="/marketplace/search.php"><?=h(t('Alle Entdeckungen'))?></a></section><?php endif;?><div class="form-grid"><?php foreach($threads as $thread):$encrypted=(int)$thread['cipher_version']===2;?><article class="panel"><p class="eyebrow"><?=h($thread['peer_name'])?><?php if($thread['unread']): ?> · <?=h(t('e2ee.legacy_unread'))?><?php endif; ?></p><h2><a href="/user/<?=$encrypted?'secure-chat':'chat'?>.php?listing_id=<?=(int)$thread['listing_id']?>&amp;user_id=<?=(int)$thread['peer_id']?>"><?=h($thread['title'])?></a></h2><p><?=h($encrypted?t('e2ee.placeholder'):mb_strimwidth(chat_message_plain($thread['message_text'],(int)$thread['cipher_version']),0,150,'…'))?></p><small><?=h($thread['created_at'])?> UTC</small></article><?php endforeach;?></div><nav class="pagination" aria-label="<?=h($pageTitle)?>"><?php if($page>1):?><a href="?page=<?=$page-1?>"><?=h(t('Zurück'))?></a><?php endif;?><span><?=h(t('Seite {page} von {pages}',['page'=>$page,'pages'=>max(1,(int)ceil($total/25))]))?></span><?php if($page*25<$total):?><a href="?page=<?=$page+1?>"><?=h(t('Weiter'))?></a><?php endif;?></nav></main><?php include __DIR__.'/../includes/footer.php';?>
